mapper.select:
SELECT id, project_id, title, description, priority, status, deadline,
creator_id, assignee_id, create_time, update_time
FROM task
WHERE project_id = #{projectId}

    AND status = #{status}


    AND priority = #{priority}

ORDER BY create_time DESC

mapper.update:
UPDATE task
SET status = #{status}, update_time = NOW()
WHERE id = #{id}

UPDATE task
SET assignee_id = #{assigneeId}, update_time = NOW()
WHERE id = #{id}
